mapper.select:
SELECT
    m.id,
    m.alarm_code AS alarmCode,
    m.module_name AS moduleName,
    m.abnormal_type_id AS abnormalTypeId,
    m.alarm_level_id AS alarmLevelId,
    m.alarm_time AS alarmTime,
    m.server_info AS serverInfo,
    m.alarm_status_id AS alarmStatusId,
    m.check_reason AS checkReason,
    m.repair_voucher AS repairVoucher,
    m.repair_time AS repairTime,
    m.remark,
    m.reserve1,
    m.reserve2,
m.creator,
m.updater,
m.deleted,
m.create_time AS createTime,
m.update_time AS updateTime,
a.typename AS abnormalName,
g.typename AS alarmLevelName,
s.typename AS alarmStatusName
FROM module_alarm_record m
LEFT JOIN abnormal_type a ON m.abnormal_type_id = a.id
LEFT JOIN alarm_grade g ON m.alarm_level_id = g.id
LEFT JOIN alarm_status s ON m.alarm_status_id = s.id
WHERE m.deleted = 0

    AND m.alarm_code = #{reqVO.alarmCode}


    AND m.module_name LIKE CONCAT('%', #{reqVO.moduleName}, '%')


    AND m.abnormal_type_id = #{reqVO.abnormalTypeId}


    AND m.alarm_level_id = #{reqVO.alarmLevelId}


    AND m.alarm_time BETWEEN #{reqVO.alarmTime[0]} AND #{reqVO.alarmTime[1]}


    AND m.server_info = #{reqVO.serverInfo}


    AND m.alarm_status_id = #{reqVO.alarmStatusId}


    AND m.check_reason = #{reqVO.checkReason}


    AND m.repair_voucher = #{reqVO.repairVoucher}


    AND m.repair_time BETWEEN #{reqVO.repairTime[0]} AND #{reqVO.repairTime[1]}


    AND m.remark = #{reqVO.remark}


    AND m.reserve1 = #{reqVO.reserve1}


    AND m.reserve2 = #{reqVO.reserve2}


    AND m.creator = #{reqVO.creator}


    AND m.updater = #{reqVO.updater}


    AND m.deleted = #{reqVO.deleted}


    AND m.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}


    AND m.update_time BETWEEN #{reqVO.updateTime[0]} AND #{reqVO.updateTime[1]}

ORDER BY m.id DESC

SELECT m.alarm_status_id AS alarmStatusId, COUNT(*) AS count FROM module_alarm_record m WHERE m.deleted = 0
AND m.alarm_time >= #{startTime}
AND m.alarm_time <= #{endTime}
GROUP BY m.alarm_status_id

SELECT m.module_name AS `name`, COUNT(*) AS `value` FROM module_alarm_record m WHERE m.deleted = 0
AND m.alarm_time >= #{startTime}
AND m.alarm_time <= #{endTime}
GROUP BY m.module_name ORDER BY `value` DESC

SELECT DATE(m.repair_time) AS `date`, AVG(TIMESTAMPDIFF(HOUR, m.alarm_time, m.repair_time)) AS repairTime FROM module_alarm_record m WHERE m.deleted = 0 AND m.alarm_status_id = 4 AND m.repair_time IS NOT NULL
AND m.alarm_time >= #{startTime}
AND m.alarm_time <= #{endTime}
GROUP BY DATE(m.repair_time) ORDER BY `date` ASC
